snippet_css:
:root{
  --bg: #FAF7F2;
  --fg: #1A1A1A;
  --muted: #57534E;
  --surface: #FFFFFF;
  --border: #D9D4CC;
  --accent: #C8102E;
  --accent-fg: #FFFFFF;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: linear-gradient(135deg,#2B2B2B,#8A8580);
  --media-bg: linear-gradient(160deg,#6E6A64,#D9D4CC);
  --cta-bg: #1A1A1A;
  --input-bg: #FFFFFF;
  --ok: #1F6B45;
  --warn: #C8102E;
  --font-display: 'Playfair Display','Noto Serif TC',serif;
  --font-body: 'Source Serif 4','Noto Serif TC',serif;
  --font-mono: Inter,ui-sans-serif,system-ui,sans-serif;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
